SELECT 7 / 2 AS division, 7 % 2 AS resto, 7.0 / 2 AS con_decimales;
SELECT precio - costo
FROM productos
LIMIT 2;

SELECT nombre AS Producto,
       precio AS "Precio CLP",
       precio - costo AS "Margen $"
FROM productos
LIMIT 3;
SELECT nombre AS 'Producto' FROM productos LIMIT 1;

SELECT DISTINCT estado FROM pedidos;
SELECT DISTINCT region FROM clientes;
SELECT DISTINCT region, comuna FROM clientes;

SELECT sku, nombre, precio
FROM productos
WHERE precio >= 100000;

SELECT nombre, apellido, comuna
FROM clientes
WHERE comuna = 'Las Condes';

SELECT nombre, apellido
FROM clientes
WHERE comuna = 'las condes';

SELECT nombre, apellido, comuna, region
FROM clientes
WHERE region = 'O''Higgins';

SELECT sku, nombre, stock
FROM productos
WHERE NOT activo;

SELECT nombre, apellido, fecha_registro
FROM clientes
WHERE fecha_registro >= '2026-01-01';

SELECT sku, nombre, precio
FROM productos
WHERE precio BETWEEN 10000 AND 15000;

SELECT id, estado, metodo_pago
FROM pedidos
WHERE estado NOT IN ('entregado', 'cancelado');

SELECT sku, nombre FROM productos WHERE nombre LIKE '%bicicleta%';
SELECT sku, nombre FROM productos WHERE nombre ILIKE '%bicicleta%';
SELECT sku, nombre FROM productos WHERE sku LIKE 'C__-%';
SELECT sku, nombre FROM productos WHERE nombre LIKE '%\%%';

