-- Los 4 productos más baratos... ¿y el empate en $6.990?
SELECT sku, nombre, precio FROM productos ORDER BY precio FETCH FIRST 4 ROWS ONLY;
SELECT sku, nombre, precio FROM productos ORDER BY precio FETCH FIRST 4 ROWS WITH TIES;
-- El empate se calcula con TODAS las columnas del ORDER BY
SELECT sku, nombre, precio FROM productos ORDER BY precio, sku FETCH FIRST 4 ROWS WITH TIES;
-- Sin ORDER BY no hay empates que calcular
SELECT sku, nombre, precio FROM productos FETCH FIRST 4 ROWS WITH TIES;

